llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Cicaprost, a prostacyclin analogue with a similar bicyclic hydroxy-acid core, showed complete absolute oral bioavailability in healthy volunteers after oral dosing, directly supporting high F for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Iloprost, another prostacyclin analogue, showed absolute oral bioavailability of 56–63% in patients, supporting high oral bioavailability for the query's analogue class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "FK788, a prostacyclin-receptor agonist containing the same carboxymethoxy-benzene motif as the query, had 55% oral bioavailability in healthy volunteers, supporting a high-F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Pravastatin, a polar hydroxy-acid drug, had only about 17% oral bioavailability in humans; however, its different scaffold and transporter-mediated hepatic disposition make this low-F evidence less transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a prostacyclin-like bicyclic hydroxy acid. Direct human data on close structural analogues—cicaprost (complete), iloprost (56–63%), and FK788 (55%)—consistently support high oral bioavailability. The low-F statin evidence is less transferable due to different scaffold and disposition mechanisms. Fed-state conditions are unlikely to reverse this class-level high-F trend.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the exact query molecule.",
    "No fed-state-specific bioavailability data for the query or its closest analogues.",
    "Low Morgan similarity scores to all evidence molecules increase structural transfer uncertainty.",
    "Potential first-pass metabolism or transporter-mediated clearance of the query is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

